CREATE SCHEMA core;
CREATE TABLE core.customer AS SELECT DISTINCT customer_unique_id AS customer_key FROM raw.olist_customers_dataset;
ALTER TABLE core.customer ADD PRIMARY KEY(customer_key);
CREATE TABLE core.order_customer AS SELECT customer_id,customer_unique_id AS customer_key,customer_zip_code_prefix AS zip_prefix,customer_city AS city,customer_state AS state FROM raw.olist_customers_dataset;
ALTER TABLE core.order_customer ADD PRIMARY KEY(customer_id), ADD FOREIGN KEY(customer_key) REFERENCES core.customer;
CREATE TABLE core.orders AS SELECT order_id,customer_id,order_status AS status,order_purchase_timestamp::timestamp AS purchased_at,order_approved_at::timestamp AS approved_at,order_delivered_carrier_date::timestamp AS carrier_at,order_delivered_customer_date::timestamp AS delivered_at,order_estimated_delivery_date::timestamp AS estimated_at FROM raw.olist_orders_dataset;
ALTER TABLE core.orders ADD PRIMARY KEY(order_id), ADD FOREIGN KEY(customer_id) REFERENCES core.order_customer, ALTER COLUMN purchased_at SET NOT NULL;
CREATE TABLE core.category AS SELECT product_category_name AS category_key,product_category_name_english AS english_name FROM raw.product_category_name_translation;
ALTER TABLE core.category ADD PRIMARY KEY(category_key);
CREATE TABLE core.product AS SELECT p.product_id,coalesce(p.product_category_name,'unknown') AS category_key,coalesce(c.english_name,p.product_category_name,'unknown') AS category_name,p.product_weight_g::numeric AS weight_g FROM raw.olist_products_dataset p LEFT JOIN core.category c ON c.category_key=p.product_category_name;
ALTER TABLE core.product ADD PRIMARY KEY(product_id);
CREATE TABLE core.seller AS SELECT seller_id,seller_zip_code_prefix AS zip_prefix,seller_city AS city,seller_state AS state FROM raw.olist_sellers_dataset;
ALTER TABLE core.seller ADD PRIMARY KEY(seller_id);
CREATE TABLE core.order_item AS SELECT order_id,order_item_id::int AS item_sequence,product_id,seller_id,shipping_limit_date::timestamp AS shipping_limit_at,price::numeric(14,2) AS price,freight_value::numeric(14,2) AS freight FROM raw.olist_order_items_dataset;
ALTER TABLE core.order_item ADD PRIMARY KEY(order_id,item_sequence), ADD FOREIGN KEY(order_id) REFERENCES core.orders, ADD FOREIGN KEY(product_id) REFERENCES core.product, ADD FOREIGN KEY(seller_id) REFERENCES core.seller, ADD CHECK(price>=0), ADD CHECK(freight>=0);
CREATE TABLE core.payment AS SELECT order_id,payment_sequential::int AS payment_sequence,payment_type,payment_installments::int AS installments,payment_value::numeric(14,2) AS amount FROM raw.olist_order_payments_dataset;
ALTER TABLE core.payment ADD PRIMARY KEY(order_id,payment_sequence), ADD FOREIGN KEY(order_id) REFERENCES core.orders, ADD CHECK(amount>=0);
CREATE TABLE core.review AS SELECT source_row AS review_record_key,review_id,order_id,review_score::int AS score,review_creation_date::timestamp AS created_at,review_answer_timestamp::timestamp AS answered_at FROM raw.olist_order_reviews_dataset;
ALTER TABLE core.review ADD PRIMARY KEY(review_record_key), ADD FOREIGN KEY(order_id) REFERENCES core.orders, ADD CHECK(score BETWEEN 1 AND 5);
COMMENT ON TABLE core.review IS 'Source review_id is not assumed unique. Stable source row is the record key. Review text stays in raw source only.';
